Combine(dir,"native-dashboard.png"));}f.ShowPage("projects");Application.DoEvents();using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(0,0,f.Width,f.Height));image.Save(Path.Combine(dir,"native-projects.png"));}using(var quote=new QuoteForm(bridge,state,null,row=>false)){quote.Show();Application.DoEvents();using(var image=new Bitmap(quote.Width,quote.Height)){quote.DrawToBitmap(image,new Rectangle(0,0,quote.Width,quote.Height));image.Save(Path.Combine(dir,"native-quote.png"));}quote.Close();}foreach(string kind in new[]{"straight","L","U"}){D settings=J.Row("shape",kind,"height",2800,"risers",16,"split",8,"going",260,"width",900,"thickness",30,"nosing",30,"landing",1000,"gap",100,"spaceX",5000,"spaceY",3000);D model=bridge.Call("stairs",settings);if(J.Num(model,"rise")!=175||J.Num(model,"treadCount")!=(kind=="straight"?15:14)||J.Bool(model,"safetyApproved"))throw new Exception("Geometry test failed");string obj=StairDesignForm.ToObj(model);if(obj.Split('\n').Count(line=>line.StartsWith("v "))!=J.Rows(model,"boxes").Count*8)throw new Exception("OBJ export mismatch");File.WriteAllText(Path.Combine(dir,"stairs-"+kind+".obj"),obj,Encoding.UTF8);using(var designer=new StairDesignForm(bridge,state,J.Row("id",Guid.NewGuid().ToString(),"name","QA 3D "+kind,"inputs",settings),row=>false)){designer.Show();Application.DoEvents();using(var image=new Bitmap(designer.Width,designer.Height)){designer.DrawToBitmap(image,new Rectangle(0,0,designer.Width,designer.Height));image.Save(Path.Combine(dir,"native-3d-"+kind+".png"));}designer.Close();}}ExtraValidation.Run(f,bridge,user,state,dir);BusinessValidation.Run(f,bridge,dir);RememberValidation.Run(bridge,dir);f.Close();}File.WriteAllText(Path.Combine(dir,"self-test.json"),"{\"nativeWindow\":true,\"login\":true,\"save\":true,\"calculation\":true,\"browserUsed\":false}",Encoding.UTF8);}return 0;}
